    "question": "How do you work out what needs fixing?",
    "is_question": true,
    "form": "Mina’s job-card sequence: reported problem, finding, parts, work and test ride, with a proposed handover.",
    "object": "One packet of six shallow 3D job cards carrying project evidence.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The sequence combines Mina’s actual job-card routine, garage-floor inventory, cracked flange, charger contribution and untested bracket."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The cards organise problem/finding comparisons, personal contributions and evidence status, so removing them loses a visual explanation rather than only atmosphere."
    },
    "depth": {
      "result": "pass",
      "reason": "The inventory develops through diagnosis, parts and contributions into results and a concluding handover."
    },
    "clipart": {
      "result": "pass",
      "reason": "The job-card packet comes from Mina’s confirmed working routine rather than a stock engineering emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan preserves group attribution and modelled-result qualifications while omitting the team ranking, guessed repair count and nonexistent testimonials."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The first screen specifies Mina’s name, engineering context, charger contribution and immediate contact access without requiring scrolling."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening question and job-card labels use ordinary language supported by concrete, appropriately qualified engineering evidence."
    }
  },
  "copied_example": false,
  "covers": {
    "phone": true,
    "reduced_motion": true,
    "no_3d": true,
    "other_needs": true,
    "look_and_type": true
